param([string]$PythonExe='python')
$ErrorActionPreference='Stop'
. "$PSScriptRoot/../PythonContract.ps1"
$temp=Join-Path ([IO.Path]::GetTempPath()) ('python-hidden-source-'+[guid]::NewGuid().ToString('N'))
$null=New-Item -ItemType Directory -Path (Join-Path $temp 'src') -Force
$source=Join-Path $temp 'src/probe.py'
"VALUE = 'pinned source'" | Set-Content $source
"__pycache__/`n*.pyc`n*.pyo`nsrc/ignored/" | Set-Content (Join-Path $temp '.gitignore')
$null=Invoke-PythonGit $temp @('init','--quiet')
$null=Invoke-PythonGit $temp @('add','.')
$null=Invoke-PythonGit $temp @('-c','user.name=Test','-c','user.email=test@example.invalid','commit','--quiet','-m','Fixture')
$sha=(Invoke-PythonGit $temp @('rev-parse','HEAD')).Trim()
Assert-PythonSource $temp $sha
function RejectHidden([string]$Name,[scriptblock]$Action) {
    $rejected=$false
    try { & $Action | Out-Null } catch { $rejected=$true }
    if (!$rejected) { throw "Unsafe hidden source accepted: $Name" }
}
foreach ($flag in @('assume-unchanged','skip-worktree')) {
    $null=Invoke-PythonGit $temp @('update-index',"--$flag",'src/probe.py')
    # Reject flags even when bytes currently match: the next read must not trust them.
    RejectHidden "$flag flag" { Assert-PythonSource $temp $sha }
    "VALUE = 'hidden edit'" | Set-Content $source
    if (@(Invoke-PythonGit $temp @('status','--porcelain')).Count) { throw 'Fixture did not hide the edit from status.' }
    RejectHidden "$flag hidden mutation" { Assert-PythonSource $temp $sha }
    $null=Invoke-PythonGit $temp @('update-index',"--no-$flag",'src/probe.py')
    $null=Invoke-PythonGit $temp @('restore','src/probe.py')
}
# Create real unchecked-hash bytecode, then restore the exact committed source.
& $PythonExe -c 'import pathlib,py_compile,sys; p=pathlib.Path(sys.argv[1]); p.write_text("VALUE = "+repr("unchecked cached code")+"\n"); py_compile.compile(str(p),doraise=True,invalidation_mode=py_compile.PycInvalidationMode.UNCHECKED_HASH)' $source
if ($LASTEXITCODE -ne 0) { throw 'Could not prepare unchecked-hash cache regression.' }
$null=Invoke-PythonGit $temp @('restore','src/probe.py')
$observed=& $PythonExe -B -c 'import sys; sys.path.insert(0,sys.argv[1]); import probe; print(probe.VALUE)' (Join-Path $temp 'src')
if ($LASTEXITCODE -ne 0 -or $observed -cne 'unchecked cached code') { throw 'Regression fixture must prove -B still executes unchecked-hash bytecode.' }
if (@(Invoke-PythonGit $temp @('status','--porcelain')).Count) { throw 'Cache regression must be invisible to ordinary status.' }
RejectHidden 'unchecked-hash ignored cached code' { Assert-PythonSource $temp $sha }
# Remove only the generated bytecode files at this known disposable fixture path.
Get-ChildItem -LiteralPath (Join-Path $temp 'src/__pycache__') -File | ForEach-Object { Remove-Item -LiteralPath $_.FullName }
Assert-PythonSource $temp $sha
$null=New-Item -ItemType Directory -Path (Join-Path $temp 'src/ignored')
"VALUE = 'ignored executable source'" | Set-Content (Join-Path $temp 'src/ignored/payload.py')
RejectHidden 'ignored src input' { Assert-PythonSource $temp $sha }
Remove-Item -LiteralPath (Join-Path $temp 'src/ignored/payload.py')
'ignored optimized code' | Set-Content (Join-Path $temp 'outside.pyo')
RejectHidden 'ignored optimized bytecode outside src' { Assert-PythonSource $temp $sha }
Remove-Item -LiteralPath (Join-Path $temp 'outside.pyo')
Assert-PythonSource $temp $sha
Write-Output 'PASS: hidden index flags and mutations, real unchecked-hash cache execution despite -B, ignored source, and optimized bytecode all rejected.'
